{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Apply temperature-1.1 pairwise smoothing across all four datasets, preserving the gradient at tied scores while sustaining pressure on correctly ordered pairs. Retain the 0.2 pointwise coefficient and uniform valid-position averaging. Architecture, inference, sampling and training settings remain unchanged.",
      "edits": [
        {
          "find": "    pairwise_loss = torch.nn.functional.softplus(neg_scores - pos_scores)",
          "replace": "    pairwise_loss = 1.1 * torch.nn.functional.softplus((neg_scores - pos_scores) / 1.1)"
        }
      ]
    }
  ],
  "change_summary": "Change only the pairwise loss to 1.1*softplus((s_neg-s_pos)/1.1). Predictor and checkpoint formats require no changes."
}
